-- 363: Original BrillaPrep WASSCE English Language Paper 2 theory practice paper (2024 format).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_363_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_363_guard;
INSERT INTO _migration_363_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM past_papers p WHERE p.id = 'pp_wassce_eng_2024_2' AND NOT (p.id IS 'pp_wassce_eng_2024_2' AND p.exam_type_id IS 'exam_wassce' AND p.subject_id IS 'subj_wassce_english' AND p.paper_type_id IS 'paper_wassce_2' AND p.year IS '2024' AND p.month IS 'May-June' AND p.series IS 'WASSCE' AND p.title IS 'English Language Paper 2 (2024)' AND p.description IS 'WASSCE English Language theory practice: essay, comprehension and summary.' AND p.total_questions IS '8' AND p.total_marks IS '300' AND p.time_allowed IS '120' AND p.instructions IS 'Answer ONE question from Section A and ALL the questions in Sections B and C.' AND p.is_complete IS '1' AND p.is_premium IS '0' AND p.source_url IS NULL)) THEN 1 ELSE 0 END;
INSERT INTO _migration_363_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_2024_2_001' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_eng_2024_2' AND q.question_text IS 'Write a story that ends with the words: ''...so that was how Grandfather''s old bicycle saved the entire harvest.''' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'A strong response builds a clear narrative arc: an impending threat to the harvest (drought, pests or flood), the narrator''s failing attempts to help, and the old bicycle becoming the unexpected means of salvation — perhaps carrying water from a distant well trip after trip, or rushing a message that brings help. The ending sentence must arise naturally from the plot rather than feel bolted on. The best answers sustain past-tense narration, use vivid but controlled description, develop one or two rounded characters, and keep spelling and punctuation secure throughout.' AND q.explanation IS 'A strong response builds a clear narrative arc: an impending threat to the harvest (drought, pests or flood), the narrator''s failing attempts to help, and the old bicycle becoming the unexpected means of salvation — perhaps carrying water from a distant well trip after trip, or rushing a message that brings help. The ending sentence must arise naturally from the plot rather than feel bolted on. The best answers sustain past-tense narration, use vivid but controlled description, develop one or two rounded characters, and keep spelling and punctuation secure throughout.' AND q.difficulty IS 'medium' AND q.points IS '40' AND q.marks IS '40' AND q.time_limit IS NULL AND q.question_number IS '1' AND q.section IS 'A' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_2024_2_001' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_eng_2024_2_001' AND NOT (e.question_id IS 'q_eng_2024_2_001' AND e.word_limit_min IS '250' AND e.word_limit_max IS '600' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Content: relevance, depth and development of ideas","marks":10},{"point":"Organization: paragraphing, coherence and logical flow","marks":10},{"point":"Expression: register, vocabulary and sentence control","marks":15},{"point":"Mechanical accuracy: spelling, punctuation and grammar","marks":5}]}' AND e.model_answer IS 'A strong response builds a clear narrative arc: an impending threat to the harvest (drought, pests or flood), the narrator''s failing attempts to help, and the old bicycle becoming the unexpected means of salvation — perhaps carrying water from a distant well trip after trip, or rushing a message that brings help. The ending sentence must arise naturally from the plot rather than feel bolted on. The best answers sustain past-tense narration, use vivid but controlled description, develop one or two rounded characters, and keep spelling and punctuation secure throughout.' AND e.marking_rubric IS NULL AND e.required_points IS '["A narrative plot in which the bicycle plausibly saves the harvest","The required closing words used verbatim and earned by the story","Consistent past-tense narration with paragraphing"]' AND e.optional_points IS '["Dialogue that advances the plot","Sensory description of the farm setting","A moment of suspense before the resolution"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_363_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_2024_2_002' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_eng_2024_2' AND q.question_text IS 'Write an article for your school magazine on the topic: ''Mobile phones in the classroom: helpful tool or harmful distraction?''' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'A strong article takes a clear position while acknowledging the other side. It opens with a headline and an engaging introduction, presents two or three developed points — for example, instant access to reference material and educational apps versus loss of attention, cheating and cyber-distraction — supports each with a concrete classroom illustration, and closes with a recommendation such as supervised, purpose-bound phone use. Register should be semi-formal and lively, addressed to fellow students, with a byline and headline marking the article format.' AND q.explanation IS 'A strong article takes a clear position while acknowledging the other side. It opens with a headline and an engaging introduction, presents two or three developed points — for example, instant access to reference material and educational apps versus loss of attention, cheating and cyber-distraction — supports each with a concrete classroom illustration, and closes with a recommendation such as supervised, purpose-bound phone use. Register should be semi-formal and lively, addressed to fellow students, with a byline and headline marking the article format.' AND q.difficulty IS 'medium' AND q.points IS '40' AND q.marks IS '40' AND q.time_limit IS NULL AND q.question_number IS '2' AND q.section IS 'A' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_2024_2_002' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_eng_2024_2_002' AND NOT (e.question_id IS 'q_eng_2024_2_002' AND e.word_limit_min IS '250' AND e.word_limit_max IS '600' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Content: relevance, depth and development of ideas","marks":10},{"point":"Organization: paragraphing, coherence and logical flow","marks":10},{"point":"Expression: register, vocabulary and sentence control","marks":15},{"point":"Mechanical accuracy: spelling, punctuation and grammar","marks":5}]}' AND e.model_answer IS 'A strong article takes a clear position while acknowledging the other side. It opens with a headline and an engaging introduction, presents two or three developed points — for example, instant access to reference material and educational apps versus loss of attention, cheating and cyber-distraction — supports each with a concrete classroom illustration, and closes with a recommendation such as supervised, purpose-bound phone use. Register should be semi-formal and lively, addressed to fellow students, with a byline and headline marking the article format.' AND e.marking_rubric IS NULL AND e.required_points IS '["Article format: headline and, ideally, a byline","A clear, defensible position on the question","At least two developed supporting points with classroom illustrations"]' AND e.optional_points IS '["Acknowledgement of the opposing view","A practical recommendation in the conclusion","Rhetorical questions or direct address to engage readers"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_363_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_2024_2_003' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_eng_2024_2' AND q.question_text IS 'Write a letter to the District Chief Executive of your area explaining three causes of poor sanitation in your community and suggesting two ways the Assembly can help solve the problem.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'A strong answer uses full formal-letter format: writer''s address, date, recipient''s designation and address, salutation, a heading in capitals, body paragraphs and a formal subscription. The body identifies three distinct causes — for example, irregular refuse collection, too few public waste bins, and open drains that residents misuse — and links each to observable effects such as cholera outbreaks or flooding. It then makes two actionable suggestions, such as a scheduled collection service and a community bin programme with by-law enforcement. Tone is respectful and persuasive throughout.' AND q.explanation IS 'A strong answer uses full formal-letter format: writer''s address, date, recipient''s designation and address, salutation, a heading in capitals, body paragraphs and a formal subscription. The body identifies three distinct causes — for example, irregular refuse collection, too few public waste bins, and open drains that residents misuse — and links each to observable effects such as cholera outbreaks or flooding. It then makes two actionable suggestions, such as a scheduled collection service and a community bin programme with by-law enforcement. Tone is respectful and persuasive throughout.' AND q.difficulty IS 'medium' AND q.points IS '40' AND q.marks IS '40' AND q.time_limit IS NULL AND q.question_number IS '3' AND q.section IS 'A' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_2024_2_003' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_eng_2024_2_003' AND NOT (e.question_id IS 'q_eng_2024_2_003' AND e.word_limit_min IS '250' AND e.word_limit_max IS '600' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Content: relevance, depth and development of ideas","marks":10},{"point":"Organization: paragraphing, coherence and logical flow","marks":10},{"point":"Expression: register, vocabulary and sentence control","marks":15},{"point":"Mechanical accuracy: spelling, punctuation and grammar","marks":5}]}' AND e.model_answer IS 'A strong answer uses full formal-letter format: writer''s address, date, recipient''s designation and address, salutation, a heading in capitals, body paragraphs and a formal subscription. The body identifies three distinct causes — for example, irregular refuse collection, too few public waste bins, and open drains that residents misuse — and links each to observable effects such as cholera outbreaks or flooding. It then makes two actionable suggestions, such as a scheduled collection service and a community bin programme with by-law enforcement. Tone is respectful and persuasive throughout.' AND e.marking_rubric IS NULL AND e.required_points IS '["Complete formal-letter layout with addresses, date, salutation, heading and subscription","Three clearly distinguished causes of poor sanitation","Two actionable suggestions addressed to the Assembly"]' AND e.optional_points IS '["Specific local details naming the community","Courteous, formal register sustained to the close"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_363_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_2024_2_004' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_eng_2024_2' AND q.question_text IS 'As the principal speaker for your school''s debate club, write your speech for or against the motion: ''Day schooling is better than boarding schooling for senior high students.''' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'A strong debate speech opens with the vocative address (Chairperson, Panel of Judges, Ladies and Gentlemen) and a firm declaration of the side taken. It then advances three or four distinct arguments — for the motion: parental supervision, lower cost, freedom from hostel distractions; against it: structured prep time, independence, peer learning — each developed with an example or appeal to the audience''s experience. Rhetorical questions, rebuttal of the opposing side''s strongest claim, and a rousing conclusion mark the best speeches. Persuasive, spirited register is sustained without sliding into insult.' AND q.explanation IS 'A strong debate speech opens with the vocative address (Chairperson, Panel of Judges, Ladies and Gentlemen) and a firm declaration of the side taken. It then advances three or four distinct arguments — for the motion: parental supervision, lower cost, freedom from hostel distractions; against it: structured prep time, independence, peer learning — each developed with an example or appeal to the audience''s experience. Rhetorical questions, rebuttal of the opposing side''s strongest claim, and a rousing conclusion mark the best speeches. Persuasive, spirited register is sustained without sliding into insult.' AND q.difficulty IS 'medium' AND q.points IS '40' AND q.marks IS '40' AND q.time_limit IS NULL AND q.question_number IS '4' AND q.section IS 'A' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Argue' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_2024_2_004' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_eng_2024_2_004' AND NOT (e.question_id IS 'q_eng_2024_2_004' AND e.word_limit_min IS '250' AND e.word_limit_max IS '600' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Content: relevance, depth and development of ideas","marks":10},{"point":"Organization: paragraphing, coherence and logical flow","marks":10},{"point":"Expression: register, vocabulary and sentence control","marks":15},{"point":"Mechanical accuracy: spelling, punctuation and grammar","marks":5}]}' AND e.model_answer IS 'A strong debate speech opens with the vocative address (Chairperson, Panel of Judges, Ladies and Gentlemen) and a firm declaration of the side taken. It then advances three or four distinct arguments — for the motion: parental supervision, lower cost, freedom from hostel distractions; against it: structured prep time, independence, peer learning — each developed with an example or appeal to the audience''s experience. Rhetorical questions, rebuttal of the opposing side''s strongest claim, and a rousing conclusion mark the best speeches. Persuasive, spirited register is sustained without sliding into insult.' AND e.marking_rubric IS NULL AND e.required_points IS '["Debate format: vocative opening and clear declaration of stance","At least three distinct, developed arguments for the chosen side","A persuasive conclusion that restates the stance"]' AND e.optional_points IS '["A rebuttal anticipating the opposing side","Rhetorical devices: questions, repetition, direct address"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_363_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_2024_2_005' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_eng_2024_2' AND q.question_text IS 'Describe a busy market in your town on the morning of a festival, and explain what the scene reveals about your community.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'A strong descriptive essay appeals to at least three senses: the colours of cloth stalls and produce, the noise of bargaining and festival drums, the smells of kelewele and fresh bread. It organizes the scene spatially — entrance, food section, cloth section — or chronologically through the morning. The second half moves from description to interpretation: the scene shows communal solidarity, the importance of trade to livelihoods, or how tradition and commerce intertwine. The best answers use precise vocabulary, varied sentence openings and controlled imagery without purple overload.' AND q.explanation IS 'A strong descriptive essay appeals to at least three senses: the colours of cloth stalls and produce, the noise of bargaining and festival drums, the smells of kelewele and fresh bread. It organizes the scene spatially — entrance, food section, cloth section — or chronologically through the morning. The second half moves from description to interpretation: the scene shows communal solidarity, the importance of trade to livelihoods, or how tradition and commerce intertwine. The best answers use precise vocabulary, varied sentence openings and controlled imagery without purple overload.' AND q.difficulty IS 'medium' AND q.points IS '40' AND q.marks IS '40' AND q.time_limit IS NULL AND q.question_number IS '5' AND q.section IS 'A' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Describe' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_2024_2_005' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_eng_2024_2_005' AND NOT (e.question_id IS 'q_eng_2024_2_005' AND e.word_limit_min IS '250' AND e.word_limit_max IS '600' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Content: relevance, depth and development of ideas","marks":10},{"point":"Organization: paragraphing, coherence and logical flow","marks":10},{"point":"Expression: register, vocabulary and sentence control","marks":15},{"point":"Mechanical accuracy: spelling, punctuation and grammar","marks":5}]}' AND e.model_answer IS 'A strong descriptive essay appeals to at least three senses: the colours of cloth stalls and produce, the noise of bargaining and festival drums, the smells of kelewele and fresh bread. It organizes the scene spatially — entrance, food section, cloth section — or chronologically through the morning. The second half moves from description to interpretation: the scene shows communal solidarity, the importance of trade to livelihoods, or how tradition and commerce intertwine. The best answers use precise vocabulary, varied sentence openings and controlled imagery without purple overload.' AND e.marking_rubric IS NULL AND e.required_points IS '["Vivid sensory description of the market on a festival morning","An explicit explanation of what the scene reveals about the community","Coherent spatial or chronological organization"]' AND e.optional_points IS '["Figures of speech used sparingly and aptly","A closing reflection that ties description to meaning"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_363_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_2024_2_006' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_eng_2024_2' AND q.question_text IS 'A friend in another school wants to join the reading club in your school. Write a letter to your friend describing the activities of the club and explaining two benefits of belonging to it.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'A strong informal letter carries the writer''s address, date, an affectionate salutation and a warm subscription with first name only. The body describes concrete club activities — weekly reading sessions, book reviews, debates on characters, author visits — and explains two benefits, such as improved vocabulary and comprehension for examinations, and confidence in public speaking from presenting reviews. The tone is friendly and enthusiastic, contractions are acceptable, and the letter ends by encouraging the friend to join or explaining how membership works.' AND q.explanation IS 'A strong informal letter carries the writer''s address, date, an affectionate salutation and a warm subscription with first name only. The body describes concrete club activities — weekly reading sessions, book reviews, debates on characters, author visits — and explains two benefits, such as improved vocabulary and comprehension for examinations, and confidence in public speaking from presenting reviews. The tone is friendly and enthusiastic, contractions are acceptable, and the letter ends by encouraging the friend to join or explaining how membership works.' AND q.difficulty IS 'medium' AND q.points IS '40' AND q.marks IS '40' AND q.time_limit IS NULL AND q.question_number IS '6' AND q.section IS 'A' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Write' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_2024_2_006' AND NOT (r.batch_id IS 'wassce-paper2-theory-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_eng_2024_2_006' AND NOT (e.question_id IS 'q_eng_2024_2_006' AND e.word_limit_min IS '250' AND e.word_limit_max IS '600' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Content: relevance, depth and development of ideas","marks":10},{"point":"Organization: paragraphing, coherence and logical flow","marks":10},{"point":"Expression: register, vocabulary and sentence control","marks":15},{"point":"Mechanical accuracy: spelling, punctuation and grammar","marks":5}]}' AND e.model_answer IS 'A strong informal letter carries the writer''s address, date, an affectionate salutation and a warm subscription with first name only. The body describes concrete club activities — weekly reading sessions, book reviews, debates on characters, author visits — and explains two benefits, such as improved vocabulary and comprehension for examinations, and confidence in public speaking from presenting reviews. The tone is friendly and enthusiastic, contractions are acceptable, and the letter ends by encouraging the friend to join or explaining how membership works.' AND e.marking_rubric IS NULL AND e.required_points IS '["Informal-letter format: one address, date, salutation and friendly subscription","A description of at least two club activities","Two clearly explained benefits of membership"]' AND e.optional_points IS '["Personal anecdote about the writer''s own improvement","Practical detail on how the friend can join"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_363_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_2024_2_007' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_eng_2024_2' AND q.question_text IS 'Read the passage carefully and answer ALL the questions that follow. — "When the assembly plant opened on the edge of town, Aba expected only jobs. What the town got first was dust. Trucks roared through the market road from dawn, and shopkeepers wiped their wares twice before noon. Within a year, however, the company had tarred the road, drilled two boreholes and started a night class for young apprentices. Some residents still grumbled that the noise never stopped, but even they admitted their children no longer travelled to the city to learn a trade."' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Aba expected the plant to bring only jobs (employment) to the town. (b) Dust from the trucks, and the noise of trucks roaring through the market road from dawn. (c) It tarred the road, drilled two boreholes, and started a night class for young apprentices. (d) Because their children could now learn a trade at home instead of travelling to the city. (e) Young people learning a trade or skill under training. (f) The writer is balanced but broadly positive, acknowledging early problems while emphasizing the benefits.' AND q.explanation IS '(a) Aba expected the plant to bring only jobs (employment) to the town. (b) Dust from the trucks, and the noise of trucks roaring through the market road from dawn. (c) It tarred the road, drilled two boreholes, and started a night class for young apprentices. (d) Because their children could now learn a trade at home instead of travelling to the city. (e) Young people learning a trade or skill under training. (f) T