4_2_005', 'q_eng_2024_2_006', 'q_eng_2024_2_007', 'q_eng_2024_2_008')) = 8 AND (SELECT COUNT(*) FROM essay_questions WHERE question_id IN ('q_eng_2024_2_001', 'q_eng_2024_2_002', 'q_eng_2024_2_003', 'q_eng_2024_2_004', 'q_eng_2024_2_005', 'q_eng_2024_2_006')) = 6 AND (SELECT COUNT(*) FROM structured_question_parts WHERE question_id IN ('q_eng_2024_2_007', 'q_eng_2024_2_008')) = 9 THEN 1 ELSE 0 END;
DROP TABLE _migration_363_guard;
